<template>
  <div class="carolina-blue-page">
    <h3 id="head">Carolina Blue</h3>
    <p class="subtitle">University of North Carolina at Chapel Hill</p>

    <div class="map-wrapper" ref="mapWrapper">
      <div id="unc-map" ref="mapEl"></div>

      <!-- Popup anchored to the pin -->
      <transition name="popup-fade">
        <div
          v-if="selectedPlace"
          class="map-popup"
          :style="popupStyle"
          @mouseenter="cancelClose"
          @mouseleave="scheduleClose"
        >
          <button class="popup-close" @click="closePopup">✕</button>
          <p class="popup-name">{{ currentPlace.name }}</p>
          <div class="popup-grid" :style="{ gridTemplateColumns: `repeat(${currentPlace.photos.length}, 1fr)` }">
            <div
              v-for="(photo, i) in currentPlace.photos"
              :key="i"
              class="popup-slot"
              :class="{ clickable: photo.src }"
              @click="photo.src && openLightbox(i)"
            >
              <img v-if="photo.src" :src="photo.src" :alt="photo.caption" />
              <div v-else class="popup-placeholder"></div>
              <p class="popup-caption">{{ photo.caption }}</p>
            </div>
          </div>
          <div class="popup-tail"></div>
        </div>
      </transition>

      <p class="map-hint">Scroll to zoom · Drag to pan · Click a pin to view photos</p>
    </div>

    <!-- Lightbox -->
    <transition name="fade">
      <div v-if="lightbox.open" class="lightbox" @click.self="lightbox.open = false">
        <div class="lightbox-content">
          <button class="lb-close" @click="lightbox.open = false">✕</button>
          <img :src="currentPlace.photos[lightbox.index].src" :alt="currentPlace.photos[lightbox.index].caption" />
          <button v-if="currentPlace.photos.length > 1" class="lb-nav lb-prev" @click="lightbox.index = (lightbox.index - 1 + currentPlace.photos.length) % currentPlace.photos.length">&#8592;</button>
          <button v-if="currentPlace.photos.length > 1" class="lb-nav lb-next" @click="lightbox.index = (lightbox.index + 1) % currentPlace.photos.length">&#8594;</button>
          <p class="lb-meta">
            <span class="lb-place">{{ currentPlace.name }}</span>
            <span v-if="currentPlace.photos[lightbox.index].caption"> · {{ currentPlace.photos[lightbox.index].caption }}</span>
            <span v-if="currentPlace.photos.length > 1" class="lb-count"> ({{ lightbox.index + 1 }}/{{ currentPlace.photos.length }})</span>
          </p>
        </div>
      </div>
    </transition>

    <p id="ending">UNC Chapel Hill / Exchange Spring 2026</p>
    <router-link to="/illusion" class="back-link">← Back to Illusion</router-link>
  </div>
</template>

<script>
const LEAFLET_CSS = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
const LEAFLET_JS  = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';

const SLOT_W   = 200;
const SLOT_GAP = 8;
const POPUP_PAD = 28;

const PLACES = {
  'kenan-residence': {
    name: 'Kenan Residence Hall',
    latlng: [35.9145912, -79.0474981],
    photos: [
      { src: '/img/carolina/kenan1.jpeg', caption: 'Front gate' },
      { src: '/img/carolina/kenan2.jpeg', caption: 'In my room' },
    ],
  },
  'hooker-fields': {
    name: 'Hooker Fields',
    latlng: [35.91006, -79.04451],
    photos: [
      { src: '/img/carolina/hooker1.jpeg', caption: 'Holimoli' },
    ],
  },
  'coker-arboretum': {
    name: 'Coker Arboretum',
    latlng: [35.913750, -79.048972],
    photos: [
      { src: '/img/carolina/coker1.jpeg', caption: 'Purple flow' },
    ],
  },
  'polk-place': {
    name: 'Polk Place',
    latlng: [35.9109, -79.0504],
    photos: [
       { src: '/img/carolina/polk1.jpeg', caption: 'Sun bath' },
    ],
  },
};

function loadCSS(href) {
  return new Promise((resolve) => {
    if (document.querySelector(`link[href="${href}"]`)) { resolve(); return; }
    const link = document.createElement('link');
    link.rel = 'stylesheet'; link.href = href;
    link.onload = resolve;
    document.head.appendChild(link);
  });
}

function loadJS(src) {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = src; s.onload = resolve; s.onerror = reject;
    document.head.appendChild(s);
  });
}

export default {
  name: 'CarolinaBlue',
  data() {
    return {
      selectedPlace: null,
      popupPos: { x: 0, y: 0 },
      lightbox: { open: false, index: 0 },
      places: PLACES,
      _closeTimer: null,
    };
  },
  computed: {
    currentPlace() {
      return this.selectedPlace ? this.places[this.selectedPlace] : null;
    },
    popupStyle() {
      if (!this.currentPlace) return {};
      const count = this.currentPlace.photos.length;
      const w = count * SLOT_W + (count - 1) * SLOT_GAP + POPUP_PAD;
      const mapW = this.$refs.mapEl ? this.$refs.mapEl.offsetWidth : 800;
      const left = Math.max(w / 2 + 8, Math.min(this.popupPos.x, mapW - w / 2 - 8));
      return {
        left: left + 'px',
        top: (this.popupPos.y - 14) + 'px',
        transform: 'translate(-50%, -100%)',
        width: w + 'px',
      };
    },
  },
  async mounted() {
    await loadCSS(LEAFLET_CSS);
    await loadJS(LEAFLET_JS);
    this.initMap();
  },
  beforeUnmount() {
    if (this._map) { this._map.remove(); this._map = null; }
  },
  methods: {
    initMap() {
      const L = window.L;
      this._markers = {};

      const map = L.map(this.$refs.mapEl, {
        center: [35.9116, -79.0456],
        zoom: 16,
        zoomControl: true,
      });
      this._map = map;

      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> © <a href="https://carto.com/">CARTO</a>',
        maxZoom: 19,
      }).addTo(map);

      const makeIcon = (place) => {
        const thumb = place.photos[0]?.src;
        const SIZE = 64, TAIL = 10;
        const inner = thumb
          ? `<img src="${thumb}" style="width:${SIZE}px;height:${SIZE}px;object-fit:cover;display:block;filter:grayscale(10%);" />`
          : `<div style="width:${SIZE}px;height:${SIZE}px;background:#e8e8e8;display:flex;align-items:center;justify-content:center;font-size:10px;color:#aaa;">no photo</div>`;
        return L.divIcon({
          className: '',
          html: `
            <div style="position:relative;width:${SIZE}px;filter:drop-shadow(0 3px 8px rgba(0,0,0,0.28));cursor:pointer;">
              <div style="border:2.5px solid #fff;overflow:hidden;">${inner}</div>
              <div style="position:absolute;left:50%;bottom:-${TAIL}px;transform:translateX(-50%);width:0;height:0;border-left:${TAIL}px solid transparent;border-right:${TAIL}px solid transparent;border-top:${TAIL}px solid #fff;"></div>
            </div>`,
          iconSize: [SIZE, SIZE + TAIL],
          iconAnchor: [SIZE / 2, SIZE + TAIL],
        });
      };

      map.on('click', () => this.closePopup());

      Object.entries(PLACES).forEach(([id, place]) => {
        const marker = L.marker(place.latlng, { icon: makeIcon(place) }).addTo(map);
        this._markers[id] = marker;

        const showPopup = (e) => {
          L.DomEvent.stopPropagation(e);
          clearTimeout(this._closeTimer);
          // hide this marker's icon
          marker.getElement().style.opacity = '0';
          // restore any previously hidden marker
          if (this.selectedPlace && this.selectedPlace !== id) {
            const prev = this._markers[this.selectedPlace];
            if (prev) prev.getElement().style.opacity = '1';
          }
          const pt = map.latLngToContainerPoint(place.latlng);
          this.popupPos = { x: pt.x, y: pt.y };
          this.selectedPlace = id;
        };

        marker.on('mouseover', showPopup);
        marker.on('click', showPopup);

        marker.on('mouseout', () => this.scheduleClose());
      });

      map.on('move zoom', () => {
        if (this.selectedPlace) {
          const pt = map.latLngToContainerPoint(PLACES[this.selectedPlace].latlng);
          this.popupPos = { x: pt.x, y: pt.y };
        }
      });
    },

    scheduleClose() {
      this._closeTimer = setTimeout(() => this.closePopup(), 200);
    },

    cancelClose() {
      clearTimeout(this._closeTimer);
    },

    closePopup() {
      if (this.selectedPlace && this._markers[this.selectedPlace]) {
        this._markers[this.selectedPlace].getElement().style.opacity = '1';
      }
      this.selectedPlace = null;
      this.lightbox.open = false;
    },

    openLightbox(index) {
      this.lightbox = { open: true, index };
    },
  },
};
</script>

